/* NEXA Troop Assets V25 — APPROVED BORDERLESS ARTWORK OWNER
   Exact user-approved Infantry/Lancer/Marksman T1–T12 supplied Aug 23, 2026.
   Preserves the already-loaded Fire Crystal FC1–FC10 registry from V24.
   No observers. No polling. No old troop portrait URLs.
*/
(()=>{
'use strict';
if(window.__NEXA_TROOP_ASSETS_V25__) return;
window.__NEXA_TROOP_ASSETS_V25__=true;

const priorFC =
  window.NEXA_TROOP_FIRE_CRYSTALS ||
  window.NEXA_FIRE_CRYSTAL_BADGES ||
  window.NEXA_TROOP_ASSETS?.fireCrystals ||
  {};

const portraits = {"infantry":{"t1":"data:image/webp;base64,","t2":"data:image/webp;base64,","t3":"data:image/webp;base64,","t4":"data:image/webp;base64,","t5":"data:image/webp;base64,","t6":"data:image/webp;base64,","t7":"data:image/webp;base64,","t8":"data:image/webp;base64,","t9":"data:image/webp;base64,","t10":"data:image/webp;base64,","t11":"data:image/webp;base64,","t12":"data:image/webp;base64,"},"lancer":{"t1":"data:image/webp;base64,","t2":"data:image/webp;base64,","t3":"data:image/webp;base64,","t4":"data:image/webp;base64,","t5":"data:image/webp;base64,","t6":"data:image/webp;base64,","t7":"data:image/webp;base64,","t8":"data:image/webp;base64,","t9":"data:image/webp;base64,","t10":"data:image/webp;base64,","t11":"data:image/webp;base64,","t12":"data:image/webp;base64,"},"marksman":{"t1":"data:image/webp;base64,","t2":"data:image/webp;base64,","t3":"data:image/webp;base64,","t4":"data:image/webp;base64,","t5":"data:image/webp;base64,","t6":"data:image/webp;base64,","t7":"data:image/webp;base64,","t8":"data:image/webp;base64,","t9":"data:image/webp;base64,","t10":"data:image/webp;base64,","t11":"data:image/webp;base64,","t12":"data:image/webp;base64,"}};

function normType(v){
  const s=String(v||'').toLowerCase();
  if(s.includes('infantry')) return 'infantry';
  if(s.includes('lancer')) return 'lancer';
  if(s.includes('marksman')) return 'marksman';
  return s;
}
function tierKey(v){
  const n=Math.max(1,Math.min(12,Number(v)||1));
  return 't'+n;
}
function getPortrait(type,tier){
  return portraits[normType(type)]?.[tierKey(tier)] || '';
}
function getFireCrystal(level){
  const n=Math.max(0,Math.min(10,Number(level)||0));
  if(!n) return '';
  return priorFC['fc'+n] || priorFC[n] || '';
}

window.NEXA_TROOP_PORTRAITS=portraits;
window.NEXA_TROOP_FIRE_CRYSTALS=priorFC;
window.NEXA_TROOP_ASSETS={
  version:25,
  portraits,
  fireCrystals:priorFC,
  getPortrait,
  getFireCrystal
};
document.dispatchEvent(new CustomEvent('nexa:troop-assets-ready',{detail:{version:25}}));
})();
